// @state at @now (every state when empty; the states of ADR-0004 section 3: running while the
// lease holds, otherwise queued before the first run and retrying after it), the earliest run_at
// first, after the position (@after_run_at, @after_id); a NULL @after_id starts at the first.
func (q *Queries) ListPendingJobs(ctx context.Context, arg ListPendingJobsParams) ([]ListPendingJobsRow, error) {
	rows, err := q.db.Query(ctx, listPendingJobs,
		arg.JobType,
		arg.State,
		arg.Now,
		arg.AfterID,
		arg.AfterRunAt,
		arg.BatchLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPendingJobsRow{}
	for rows.Next() {
		var i ListPendingJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Payload,
			&i.IdempotencyKey,
			&i.OrderingKey,
			&i.Attempt,
			&i.RunAt,
			&i.LockedBy,
			&i.LockedUntil,
			&i.LastError,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockOrderingKey = `-- name: LockOrderingKey :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

func (q *Queries) LockOrderingKey(ctx context.Context, lockKey string) error {
	_, err := q.db.Exec(ctx, lockOrderingKey, lockKey)
	return err
}

const nextJobOfKey = `-- name: NextJobOfKey :one
SELECT id, type, run_at FROM jobs WHERE ordering_key = $1 ORDER BY created_at, id LIMIT 1
`

type NextJobOfKeyRow struct {
	ID    string
	Type  string
	RunAt time.Time
}

func (q *Queries) NextJobOfKey(ctx context.Context, orderingKey *string) (NextJobOfKeyRow, error) {
	row := q.db.QueryRow(ctx, nextJobOfKey, orderingKey)
	var i NextJobOfKeyRow
	err := row.Scan(&i.ID, &i.Type, &i.RunAt)
	return i, err
}

const pickJob = `-- name: PickJob :one

SELECT j.id, j.ordering_key FROM jobs AS j
WHERE j.run_at <= $1 AND (j.locked_until IS NULL OR j.locked_until <= $1)
  AND NOT EXISTS (
    SELECT 1 FROM jobs AS k
    WHERE k.ordering_key = j.ordering_key AND k.id <> j.id
      AND (k.locked_until > $1 OR k.created_at < j.created_at OR (k.created_at = j.created_at AND k.id < j.id))
  )
ORDER BY j.run_at, j.id
LIMIT 1
FOR UPDATE SKIP LOCKED
`

type PickJobRow struct {
	ID          string
	OrderingKey *string
}

// A claim takes three statements in one transaction, because under READ COMMITTED a claim
// may not see the lease of a job of the same ordering key that another worker is claiming at
// the same time:
//
//  1. PickJob finds a candidate: the due, unleased job with the earliest run_at that its
//     ordering key does not hold back (no other job of the key leased or enqueued before it, by
//     (created_at, id)). FOR UPDATE SKIP LOCKED lets concurrent workers pass over the rows that
//     others are claiming instead of waiting for them.
//  2. LockOrderingKey, for a candidate with an ordering key, serializes the claims of that key
//     until the transaction ends.
//  3. ClaimJob checks the candidate again in a snapshot taken after the lock, so it sees the
//     leases committed by earlier claims of the key, and leases it.
func (q *Queries) PickJob(ctx context.Context, now time.Time) (PickJobRow, error) {
	row := q.db.QueryRow(ctx, pickJob, now)
	var i PickJobRow
	err := row.Scan(&i.ID, &i.OrderingKey)
	return i, err
}

const pickJobOfTypes = `-- name: PickJobOfTypes :one
SELECT c.id, c.ordering_key
FROM unnest($1::text[]) AS t(type)
CROSS JOIN LATERAL (
  SELECT j.id, j.ordering_key, j.run_at FROM jobs AS j
  WHERE j.type = t.type
    AND j.run_at <= $2 AND (j.locked_until IS NULL OR j.locked_until <= $2)
    AND NOT EXISTS (
      SELECT 1 FROM jobs AS k
      WHERE k.ordering_key = j.ordering_key AND k.id <> j.id
        AND (k.locked_until > $2 OR k.created_at < j.created_at OR (k.created_at = j.created_at AND k.id < j.id))
    )
  ORDER BY j.run_at, j.id
  LIMIT 1
  FOR UPDATE SKIP LOCKED
) AS c
ORDER BY c.run_at, c.id
LIMIT 1
`

type PickJobOfTypesParams struct {
	Types []string
	Now   time.Time
}

type PickJobOfTypesRow struct {
	ID          string
	OrderingKey *string
}

// PickJobOfTypes is PickJob for a worker that runs only some job types (ADR-0004 section 2): it
// takes each type's candidate from jobs_type_run_at_id and picks the earliest of them, so that a
// backlog of the other types costs nothing. A condition on PickJob would walk that backlog. The
// candidates of the other types stay locked until the transaction ends; the other workers skip
// them.
func (q *Queries) PickJobOfTypes(ctx context.Context, arg PickJobOfTypesParams) (PickJobOfTypesRow, error) {
	row := q.db.QueryRow(ctx, pickJobOfTypes, arg.Types, arg.Now)
	var i PickJobOfTypesRow
	err := row.Scan(&i.ID, &i.OrderingKey)
	return i, err
}

const releaseJob = `-- name: ReleaseJob :execrows
UPDATE jobs
SET locked_by = NULL, locked_until = NULL,
  attempt = $1, run_at = $2, last_error = $3
WHERE id = $4 AND locked_by = $5 AND attempt = $6
`

type ReleaseJobParams struct {
	NewAttempt int32
	RunAt      time.Time
	LastError  *string
	ID         string
	Worker     *string
	Attempt    int32
}

func (q *Queries) ReleaseJob(ctx context.Context, arg ReleaseJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, releaseJob,
		arg.NewAttempt,
		arg.RunAt,
		arg.LastError,
		arg.ID,
		arg.Worker,
		arg.Attempt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const requeueDeadJob = `-- name: RequeueDeadJob :execrows
INSERT INTO jobs (id, type, payload, idempotency_key, ordering_key, trace_parent, attempt, run_at, created_at)
SELECT d.id, d.type, d.payload, d.idempotency_key, d.ordering_key, d.trace_parent, 0, $1, d.created_at
FROM dead_jobs AS d
WHERE d.id = $2
ON CONFLICT (idempotency_key) DO NOTHING
`

type RequeueDeadJobParams struct {
	RunAt time.Time
	ID    string
}

func (q *Queries) RequeueDeadJob(ctx context.Context, arg RequeueDeadJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, requeueDeadJob, arg.RunAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
